package com.guocheng.mediapocket;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** 弹幕：匹配、加载、开关。没有密钥时只提示，不发请求。 */
final class DanmuController {
 static final Map<Activity,DanmuController> ALL=new WeakHashMap<>();
 final Activity a;DanmuView view;List<DanDanPlayRules.Cue> cues=new ArrayList<>();int shift;String loaded="";boolean busy,started;DanmuRules.Config cachedCfg;
 DanmuController(Activity a){this.a=a;}
 static SharedPreferences prefs(Activity a){return a.getSharedPreferences("data",0);}
 static DanmuRules.Config config(SharedPreferences p){return new DanmuRules.Config(p.getBoolean("danmu.shown",true),p.getInt("danmu.opacity",80),p.getFloat("danmu.speed",8f),p.getInt("danmu.textSp",16),p.getInt("danmu.topLines",3),p.getInt("danmu.scrollLines",8),p.getInt("danmu.bottomLines",3),p.getString("danmu.block",""),p.getString("danmu.match","auto"),p.getBoolean("danmu.remember",true));}
 static String appId(SharedPreferences p){return p.getString("danmu.appId","");}
 static String secret(SharedPreferences p){return p.getString("danmu.appSecret","");}
 static void attach(Activity a){try{DanmuController c=ALL.get(a);if(c==null){c=new DanmuController(a);ALL.put(a,c);}c.ensure();c.autostart();}catch(Exception ignored){}}
 static void tick(Activity a){DanmuController c=ALL.get(a);if(c==null||c.view==null)return;c.view.position(EmbyPlayback.position(a));DanmuRules.Config cfg=config(prefs(a));if(!cfg.same(c.cachedCfg)){c.cachedCfg=cfg;c.rebind();}}
 static void dispose(Activity a){ALL.remove(a);}
 static String label(Activity a){String why=DanDanPlayRules.reason(appId(prefs(a)),secret(prefs(a)));if(why!=null)return "弹幕：未配置";return config(prefs(a)).shown?"弹幕：开":"弹幕：关";}
 static void menu(Activity a){String why=DanDanPlayRules.reason(appId(prefs(a)),secret(prefs(a)));if(why!=null){new AlertDialog.Builder(a).setTitle("弹幕").setMessage(why).setPositiveButton("知道了",null).show();return;}DanmuRules.Config cfg=config(prefs(a));java.util.List<CinemaMenu.Item> rows=new ArrayList<>();rows.add(CinemaMenu.item(cfg.shown?"关闭弹幕":"显示弹幕",()->{prefs(a).edit().putBoolean("danmu.shown",!cfg.shown).apply();DanmuController c=ALL.get(a);if(c!=null){c.rebind();if(!cfg.shown)c.autostart();}}));rows.add(CinemaMenu.item(cfg.match.equals("manual")?"匹配：手动选集":"匹配：自动匹配",()->{String next=cfg.match.equals("manual")?"auto":"manual";prefs(a).edit().putString("danmu.match",next).apply();toast(a,"manual".equals(next)?"之后需要手动选集":"之后会自动匹配");}));rows.add(CinemaMenu.item("重新匹配",()->{DanmuController c=ALL.get(a);if(c!=null){c.loaded="";c.busy=false;c.started=true;c.search(false);}}));rows.add(CinemaMenu.item("弹幕设置",()->PlayerFeatureSettings.danmuStyle(a)));CinemaMenu.show(a,"弹幕",rows);}
 void ensure(){Object root=OnlineSubtitleSearch.field(a,"root");if(!(root instanceof FrameLayout))return;FrameLayout host=(FrameLayout)root;View found=host.findViewWithTag("mp-danmu");if(found instanceof DanmuView){view=(DanmuView)found;return;}view=new DanmuView(a);view.setTag("mp-danmu");int index=0;Object video=OnlineSubtitleSearch.field(a,"video");if(video instanceof View){View node=(View)video;android.view.ViewParent parent=node.getParent();View holder=parent==host?node:parent instanceof View&&((View)parent).getParent()==host?(View)parent:null;if(holder!=null)index=host.indexOfChild(holder)+1;}host.addView(view,Math.max(0,Math.min(index,host.getChildCount())),new FrameLayout.LayoutParams(-1,-1));rebind();}
 void rebind(){if(view!=null)view.bind(cues,config(prefs(a)));}
 void autostart(){if(started||busy)return;DanmuRules.Config cfg=config(prefs(a));if(!cfg.shown)return;if(DanDanPlayRules.reason(appId(prefs(a)),secret(prefs(a)))!=null)return;started=true;String id=PlayerOverlay.id(a);if(cfg.remember){String saved=prefs(a).getString("danmu.episode:"+id,"");if(!saved.isEmpty())try{load(Long.parseLong(saved),0);return;}catch(Exception ignored){}}if("manual".equals(cfg.match))return;search(true);}
 void search(boolean automatic){if(busy)return;String why=DanDanPlayRules.reason(appId(prefs(a)),secret(prefs(a)));if(why!=null){if(!automatic)toast(a,why);return;}busy=true;final String title=title();final int episode=episode();final String file=DanDanPlayRules.fileName(TrackSelection.stream(a).optString("url"),title);final String id=appId(prefs(a)),sec=secret(prefs(a));final int duration=durationSec();OnlineSubtitleSearch.IO.execute(()->{try{List<DanDanPlayRules.Hit> hits=DanDanPlayRules.searchHits(DanDanPlayClient.get(id,sec,DanDanPlayRules.searchQuery(title,episode)));if(hits.isEmpty())hits=DanDanPlayRules.matchHits(DanDanPlayClient.post(id,sec,DanDanPlayRules.MATCH,DanDanPlayRules.matchBody(file,duration)));else {long anime=DanDanPlayRules.loneAnime(hits);boolean needDetail=false;for(DanDanPlayRules.Hit h:hits)if(h.episodeId<=0)needDetail=true;if(needDetail&&anime>0){List<DanDanPlayRules.Hit> detail=DanDanPlayRules.animeHits(DanDanPlayClient.get(id,sec,DanDanPlayRules.animeQuery(anime)));if(!detail.isEmpty())hits=detail;}}final List<DanDanPlayRules.Hit> found=hits;a.runOnUiThread(()->{busy=false;if(a.isFinishing())return;if(found.isEmpty()){toast(a,"没有匹配到弹幕");return;}if(automatic){DanDanPlayRules.Hit pick=DanDanPlayRules.autoPick(found,episode);if(pick!=null){choose(pick);return;}}chooseDialog(found);});}catch(Exception e){a.runOnUiThread(()->{busy=false;if(!a.isFinishing())toast(a,e.getMessage()==null?"弹幕匹配失败":e.getMessage());});}});}
 void chooseDialog(List<DanDanPlayRules.Hit> hits){String[] labels=new String[hits.size()];for(int i=0;i<hits.size();i++)labels[i]=hits.get(i).label();new AlertDialog.Builder(a).setTitle("选择弹幕").setItems(labels,(d,i)->{DanDanPlayRules.Hit hit=hits.get(i);if(hit.episodeId<=0)loadAnime(hit.animeId);else choose(hit);}).setNegativeButton("关闭",null).show();}
 void loadAnime(long animeId){final String id=appId(prefs(a)),sec=secret(prefs(a));OnlineSubtitleSearch.IO.execute(()->{try{final List<DanDanPlayRules.Hit> hits=DanDanPlayRules.animeHits(DanDanPlayClient.get(id,sec,DanDanPlayRules.animeQuery(animeId)));a.runOnUiThread(()->{if(a.isFinishing())return;if(hits.isEmpty())toast(a,"这部番剧没有分集");else chooseDialog(hits);});}catch(Exception e){a.runOnUiThread(()->toast(a,e.getMessage()==null?"读取分集失败":e.getMessage()));}});}
 void choose(DanDanPlayRules.Hit hit){if(config(prefs(a)).remember)prefs(a).edit().putString("danmu.episode:"+PlayerOverlay.id(a),Long.toString(hit.episodeId)).apply();load(hit.episodeId,hit.shift);}
 void load(long episodeId,int shiftSec){final String id=appId(prefs(a)),sec=secret(prefs(a));final String key=episodeId+":"+shiftSec;if(key.equals(loaded)){rebind();return;}OnlineSubtitleSearch.IO.execute(()->{try{final List<DanDanPlayRules.Cue> next=DanDanPlayRules.comments(DanDanPlayClient.get(id,sec,DanDanPlayRules.commentQuery(episodeId)),shiftSec);a.runOnUiThread(()->{if(a.isFinishing())return;cues=next;shift=shiftSec;loaded=key;rebind();toast(a,next.isEmpty()?"这个节目还没有弹幕":"已加载 "+next.size()+" 条弹幕");});}catch(Exception e){a.runOnUiThread(()->{if(!a.isFinishing())toast(a,e.getMessage()==null?"弹幕加载失败":e.getMessage());});}});}
 int durationSec(){try{Object video=OnlineSubtitleSearch.field(a,"video");Object r=video==null?null:OnlineSubtitleSearch.call(video,"getDuration",new Class<?>[0]);int ms=r instanceof Integer?(Integer)r:0;return ms>0?ms/1000:0;}catch(Exception e){return 0;}}
 String title(){String name=PlayerOverlay.name(a);JSONObject meta=PlayerOverlay.meta(a);String raw=meta.optString("fusion.title",name);if(raw.isEmpty())raw=name;String clean=MediaMatchRules.clean(raw);return clean.isEmpty()?raw:clean;}
 int episode(){JSONObject meta=PlayerOverlay.meta(a);FusionPlaybackRules.Episode parsed=FusionPlaybackRules.episode(meta.optString("subtitleEpisode",PlayerOverlay.name(a)),meta.optString("fusion.title"));if(parsed.number>0)return parsed.number;String from=PlayerOverlayRules.fromId(PlayerOverlay.id(a));try{return from.isEmpty()?0:Integer.parseInt(from);}catch(Exception e){return 0;}}
 static void toast(Activity a,String text){PlayerOverlay.toast(a,text);}
}
